async function request(path:string,body?:unknown){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:undefined);const data=await r.json() as any;if(!r.ok)throw new Error(data.error||'Er ging iets mis. Probeer opnieuw.');return data;}

