 const [view,setView]=useState('home'),[level,setLevel]=useState('B1'),[goal,setGoal]=useState('Mbo'),[category,setCategory]=useState('Alles'),[role,setRole]=useState<UserRole>('student');
 const [activities,setActivities]=useState<Activity[]>([]),[lessons,setLessons]=useState<Lesson[]>([]),[loaded,setLoaded]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[ready,setReady]=useState(false);
 const [mission,setMission]=useState<Mission|null>(null),[messages,setMessages]=useState<Message[]>([]),[input,setInput]=useState(''),[busy,setBusy]=useState(false),[feedback,setFeedback]=useState(''),[sessionId,setSessionId]=useState(''),[saved,setSaved]=useState(false);
 const [calling,setCalling]=useState(false),[connecting,setConnecting]=useState(false),[muted,setMuted]=useState(false),[callStatus,setCallStatus]=useState(''),[seconds,setSeconds]=useState(0);
 const callAttempt=useRef(0),coachAttempt=useRef(0),coachAbort=useRef<AbortController|null>(null);
 const pc=useRef<RTCPeerConnection|null>(null),stream=useRef<MediaStream|null>(null),audio=useRef<HTMLAudioElement|null>(null),chatEnd=useRef<HTMLDivElement|null>(null);
 const [article,setArticle]=useState<number|null>(null),[word,setWord]=useState(''),[field,setField]=useState('Alles'),[game,setGame]=useState<string|null>(null),[q,setQ]=useState(0),[answer,setAnswer]=useState<number|null>(null),[score,setScore]=useState(0),[quizDone,setQuizDone]=useState(false),[gameId,setGameId]=useState(''),[quizSkills,setQuizSkills]=useState<string[]>([]),[selected,setSelected]=useState<number[]>([]),[found,setFound]=useState<string[]>([]),[gameSaved,setGameSaved]=useState(false);
 usePipPage({id:view,title:nav.find(n=>n.id===view)?.label||'Lessenmaker',level,description:'De leerling bekijkt '+(nav.find(n=>n.id===view)?.label||'de lessenmaker')+'. Leg uit hoe je hier kunt oefenen; vraag welke stap lastig is.'});
