 const reload=useCallback(async()=>{try{const d=await request('/api/state');setActivities(d.activities);setLessons(d.lessons);setLoaded(true);setError('');}catch(e){setError((e as Error).message);}},[]);
 useEffect(()=>{reload();request('/api/profile').then(d=>{setProfile(d.profile);setGoal(d.profile.goal);chooseLanguage(localStorage.getItem('taalcoach-language')||d.profile.language)}).catch(e=>setError(e.message));request('/api/me').then(d=>setRole(d.user?.role||'student')).catch(()=>{});request('/api/coach').then(d=>setReady(d.ready)).catch(()=>{});},[reload,chooseLanguage]);
 useEffect(()=>{chatEnd.current?.scrollIntoView({behavior:'smooth'});},[messages,busy]);
