 const endCall=useCallback(()=>{callAttempt.current++;stream.current?.getTracks().forEach(t=>t.stop());stream.current=null;pc.current?.close();pc.current=null;if(audio.current){audio.current.pause();audio.current.srcObject=null;}setCalling(false);setConnecting(false);setMuted(false);setCallStatus('');},[]);
 useEffect(()=>()=>{coachAttempt.current++;coachAbort.current?.abort();callAttempt.current++;stream.current?.getTracks().forEach(t=>t.stop());pc.current?.close();},[]);
