 async function record(kind:string,skill:string,id:string,detail:string){await request('/api/state',{type:'activity',kind,skill,id,detail});await reload();}
 async function send(spoken?:string){
  const utterance=(spoken??input).trim();
  if(!utterance||busy||!mission||localAI.status!=='ready')return;
  const next:Message[]=[...messages,{role:'user',content:utterance.slice(0,2000)}],attempt=++coachAttempt.current,c=new AbortController();coachAbort.current=c;
  setMessages(next);setInput('');setBusy(true);setNotice('');
  try{const text=await localCompletion([{role:'system',content:localCoachPersonality(coach)+'\n'+JSON.stringify({role:mission.role,situation:mission.description,goals:mission.goals,level,goal,field:profile.field,interests:profile.interests})},...next.slice(-10)],{signal:c.signal});if(attempt===coachAttempt.current)setMessages([...next,{role:'assistant',content:text}]);}
  catch(e){if(attempt===coachAttempt.current){setMessages(messages);setInput(next[next.length-1].content);setNotice((e as Error).message);}}
  finally{if(attempt===coachAttempt.current)setBusy(false)}
 }
 async function finish(){
  if(!mission||busy)return;endCall();setBusy(true);setNotice('');const attempt=++coachAttempt.current,c=new AbortController();coachAbort.current=c;
  try{let text=feedback;if(!text){text=reviewedReflection(await localCompletion(reflectionMessages(messages),{maxTokens:60,json:true,signal:c.signal}),messages);if(attempt!==coachAttempt.current)return;setFeedback(text);}await record('mission',mission.skill,sessionId,JSON.stringify({title:mission.title,messages,feedback:text}));if(attempt===coachAttempt.current)setSaved(true);}
  catch(e){if(attempt===coachAttempt.current)setNotice((e as Error).message);}
  finally{if(attempt===coachAttempt.current)setBusy(false)}
 }
 async function startCall(){if(!mission)return;if(!ready){setNotice('De AI-coach is nog niet verbonden. De eigenaar moet eerst de AI-koppeling activeren.');return;}setConnecting(true);setNotice('');setSeconds(0);const attempt=++callAttempt.current;try{const s=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});if(attempt!==callAttempt.current){s.getTracks().forEach(t=>t.stop());return;}stream.current=s;const p=new RTCPeerConnection();pc.current=p;const a=new Audio();a.autoplay=true;audio.current=a;p.ontrack=e=>{a.srcObject=e.streams[0];a.play().catch(()=>setNotice('Je browser blokkeert geluid. Sta audio toe voor deze site.'))};s.getTracks().forEach(t=>p.addTrack(t,s));const dc=p.createDataChannel('oai-events');dc.onopen=()=>{if(attempt!==callAttempt.current){p.close();return;}for(const message of messages.slice(-20)){dc.send(JSON.stringify({type:'conversation.item.create',item:{type:'message',role:message.role,content:[{type:message.role==='user'?'input_text':'output_text',text:message.content}]}}));}setConnecting(false);setCalling(true);setCallStatus(coachText('Pip luistert…'));dc.send(JSON.stringify({type:'response.create',response:{instructions:'Vervolg het bestaande gesprek. Stel één korte vraag en wacht dan op de leerling.'}}))};dc.onmessage=e=>{try{const v=JSON.parse(e.data);if(v.type==='conversation.item.input_audio_transcription.completed'&&v.transcript)setMessages(m=>[...m,{role:'user',content:v.transcript}]);if(v.type==='response.output_audio_transcript.done'&&v.transcript)setMessages(m=>[...m,{role:'assistant',content:v.transcript}]);if(v.type==='input_audio_buffer.speech_started')setCallStatus(coachText('Pip luistert…'));if(v.type==='response.created')setCallStatus(coachText('Pip denkt even na…'));if(v.type==='output_audio_buffer.started')setCallStatus(coachText('Pip vertelt…'));if(v.type==='response.done')setCallStatus('Jij bent aan de beurt');if(v.type==='error')setNotice('Er ging iets mis in het gesprek. Hang op en probeer opnieuw.');}catch{}};p.onconnectionstatechange=()=>{if(p.connectionState==='failed'||p.connectionState==='disconnected'){endCall();setNotice('De verbinding is verbroken. Je kunt opnieuw bellen.')}};const offer=await p.createOffer();await p.setLocalDescription(offer);const r=await fetch('/api/realtime',{method:'POST',signal:AbortSignal.timeout(35000),headers:{'Content-Type':'application/json'},body:JSON.stringify({sdp:offer.sdp,mission:mission.id,level})});if(!r.ok){const d=await r.json() as any;throw new Error(d.error)}const answer=await r.text();if(attempt!==callAttempt.current){p.close();return;}await p.setRemoteDescription({type:'answer',sdp:answer});}catch(e){if(attempt!==callAttempt.current)return;endCall();setNotice((e as Error).name==='NotAllowedError'?'Geef toegang tot je microfoon om te kunnen praten.':(e as Error).message)}}
