 {view==='content'&&<><NewsPanel field={profile.field} onPractice={article=>{setReadingSeed(article);go('atelier')}}/><div className="page-heading"><div><div className="season-label"><Coffee size={15}/> RUIMTE VOOR NIEUWSGIERIGHEID</div><h1><B>De leeshoek.</B></h1><p><B>Nieuwe woorden ontdekken, even spelen en ontspannen.</B></p></div><Picker value={field} onChange={setField} items={['Alles',...articles.map(a=>a.field)]}/></div><div className="section-heading"><div><h2><B>Een klein verhaal, nieuwe woorden</B></h2><p><B>Leesteksten voor je studie en werk · met klikbare woordhulp</B></p></div></div><div className="article-grid">{articles.map((a,i)=>(field==='Alles'||field===a.field)&&<button key={a.title} className={`article-card article-${i}`} onClick={()=>{setArticle(i);setNotice('')}}><B><div className="article-art"><a.icon size={42}/><span className="reading-label"><B>LEESTEKST · {a.time} MIN</B></span></div><div className="article-body"><span className="eyebrow"><B>{a.field}</B></span><h3><B>{a.title}</B></h3><p><B>{a.text.slice(0,95)}…</B></p><span className="text-button"><B>Lees het verhaal <ChevronRight size={16}/></B></span></div></B></button>)}</div><div className="section-heading"><div><h2><B>Spelen met taal</B></h2><p><B>Een korte pauze waar je iets van opsteekt.</B></p></div></div>{lessons.some(l=>l.status==='published')&&<section className="published-lessons"><h2><B>Jouw lessen</B></h2><div className="lesson-grid">{lessons.filter(l=>l.status==='published').map(l=><button key={l.id} className="panel lesson-card" onClick={()=>setReadLesson(l)}><B><span className="eyebrow"><B>{l.module}</B></span><h3><B>{l.title}</B></h3><span className="text-button"><B>Open les <BookOpen size={15}/></B></span></B></button>)}</div></section>}<div className="games-grid"><button className="game-card quiz-card" onClick={()=>openGame('quiz')}><B><span className="game-symbol"><B><Sparkles size={32}/></B></span><div><span className="eyebrow"><B>5 VRAGEN · 20 XP</B></span><h3><B>De taalquiz</B></h3><p><B>Test je taalgevoel. Klaar voor een uitdaging?</B></p></div><Play size={25}/></B></button><button className="game-card" onClick={()=>openGame('wordsearch')}><B><span className="game-symbol"><B><Search size={32}/></B></span><div><span className="eyebrow"><B>5 WOORDEN · 20 XP</B></span><h3><B>Woordzoeker</B></h3><p><B>Vind de schoolwoorden tussen de letters.</B></p></div><Play size={25}/></B></button></div></>}
 {view==='games'&&<><div className="page-heading"><div><div className="season-label"><Trophy size={15}/> SPEEL MET TAAL</div><h1><B>{coachText("Welkom in de speelhal van Pip.")}</B></h1><p><B>Vang woorden, kraak een kluis of daag je geheugen uit. Kies een spel en begin.</B></p></div></div><ArcadeGames onComplete={reload}/><div className="section-heading"><h2>Meer taaluitdagingen</h2></div><ChallengeGames onComplete={reload}/><div className="section-heading"><h2><B>Even opwarmen</B></h2></div><div className="games-grid"><button className="game-card" onClick={()=>openGame('quiz')}><B><Sparkles/><div><h3><B>De taalquiz</B></h3><p><B>Vijf vragen over de basis van het Nederlands.</B></p></div></B></button><button className="game-card" onClick={()=>openGame('wordsearch')}><B><Search/><div><h3><B>Woordzoeker</B></h3><p><B>Een rustige ronde met schoolwoorden.</B></p></div></B></button></div></>}
 {view==='progress'&&<><div className="page-heading"><div><div className="season-label"><Leaf size={15}/> IEDERE STAP TELT</div><h1><B>Kijk eens hoe je groeit.</B></h1><p><B>Je voortgang op basis van wat je daadwerkelijk oefent.</B></p></div></div><div className="stat-grid"><div><Sparkles/><strong><B>{xp}</B></strong><span><B>verdiende XP</B></span></div><div><Trophy/><strong><B>{levelNum}</B></strong><span><B>jouw speellevel</B></span></div><div><Flame/><strong><B>{streak}</B></strong><span><B>dagen op rij</B></span></div><div><CheckCircle2/><strong><B>{activities.length}</B></strong><span><B>afgeronde oefeningen</B></span></div></div><div className="progress-layout"><section className="panel"><div className="section-heading"><h2><B>Jouw skill map</B></h2><span className="tag"><B>Oefenervaring</B></span></div><p className="muted"><B>Elke afgeronde oefening laat je ervaring groeien. Dit is geen taalexamen of niveaubeoordeling.</B></p><div className="skill-map">{skills.map((s,i)=>{const n=activities.filter(a=>a.skill===s||(a.kind==='quiz'&&a.detail.includes(s))).length;return <div className="skill-row" key={s}><span className={`skill-node node-${i}`}><B><CheckCircle2 size={21}/></B></span><div><div className="skill-label"><b><B>{s}</B></b><span><B>{n} keer geoefend</B></span></div><Progress value={Math.min(n*10,100)}/></div></div>})}</div></section><section className="panel"><Trophy className="large-icon"/><h2><B>Speellevel {levelNum}</B></h2><p><B>{200-xp%200} XP tot je volgende level</B></p><Progress value={xp%200/2}/><h3 className="badge-heading"><B>Jouw mijlpalen</B></h3>{[{t:'De eerste stap',check:activities.length>=1,desc:'Rond je eerste oefening af'},{t:'In gesprek',check:activities.some(a=>a.kind==='mission'),desc:'Voltooi een mission'},{t:'Vaste prik',check:streak>=3,desc:'Oefen 3 dagen op rij'}].map(b=><div className={'achievement '+(b.check?'earned':'')} key={b.t}><span><B><Trophy size={19}/></B></span><div><b><B>{b.t}</B></b><small><B>{b.desc}</B></small></div>{b.check&&<Check size={18}/>}</div>)}</section></div><section className="panel history"><h2><B>Je laatste stappen</B></h2>{activities.length===0?<div className="empty-state"><Compass size={30}/><h3><B>Hier begint jouw verhaal.</B></h3><p><B>Rond een oefening af en zie hier je voortgang.</B></p><button className="primary-button" onClick={()=>openExercises('all')}><B>Kies een oefening</B></button></div>:activities.slice(0,12).map(a=><div className="history-row" key={a.id}><CheckCircle2 size={19}/><div><b><B>{a.kind==='atelier'?exerciseTitle(a.detail):a.kind==='exercise'?exerciseTitle(a.detail):a.kind==='mission'?'Gesprek afgerond':a.kind==='quiz'?'Taalquiz':a.kind==='reading'?'Leestekst gelezen':a.kind==='sentence'?'Zinsarchitect':a.kind==='editor'?'De eindredacteur':a.kind==='register'?'Zeg het tactisch':'Woordzoeker'}</B></b><small><B>{a.skill} · {new Date(a.date).toLocaleDateString('nl-NL')}</B></small></div><span><B>+{a.xp} XP</B></span></div>)}</section></>}
 {view==='teacher'&&role==='teacher_admin'&&<><div className="page-heading"><div><div className="season-label"><NotebookPen size={15}/> VOOR DOCENTEN</div><h1><B>Maak ruimte voor leren.</B></h1><p><B>Bouw modules en lessen. Jij houdt de regie over wat verschijnt.</B></p></div><button className="primary-button" onClick={()=>{setEditor({id:crypto.randomUUID(),title:'',module:'Algemeen',body:'',status:'draft'});setNotice('')}}><B><Plus size={18}/>Nieuwe les</B></button></div><div className="teacher-intro"><span className="icon-tile"><B><Sparkles size={23}/></B></span><div><h3><B>Jouw expertise, met een beetje hulp van AI.</B></h3><p><B>Laat een concept maken en pas het aan. Een les verschijnt pas wanneer jij op Publiceren klikt.</B></p></div><span className="tag"><B>Altijd eerst een concept</B></span></div>{lessons.length===0?<section className="panel empty-state"><BookOpen size={42}/><h2><B>Jouw eerste module begint met één les.</B></h2><p><B>Voeg een eigen les toe of laat de AI een concept uitwerken.</B></p><button className="outline-button" onClick={()=>setEditor({id:crypto.randomUUID(),title:'',module:'Mijn eerste module',body:'',status:'draft'})}><B><Plus size={17}/>Maak je eerste les</B></button></section>:[...new Set(lessons.map(l=>l.module))].map(mod=><section className="module-section" key={mod}><h2><B><BookOpen size={23}/>{mod}</B></h2><div className="lesson-grid">{lessons.filter(l=>l.module===mod).map(l=><button className="panel lesson-card" key={l.id} onClick={()=>{setEditor(l);setNotice('')}}><B><span className={'tag '+(l.status==='published'?'published':'')}><B>{l.status==='published'?'Gepubliceerd':'Concept'}</B></span><h3><B>{l.title}</B></h3><p><B>{l.body.slice(0,140)}…</B></p><span className="text-button"><B>Les bewerken <NotebookPen size={15}/></B></span></B></button>)}</div></section>)}<div className="info-note"><Clock size={18}/><div><b><B>Periodieke conceptlessen</B></b><p><B>Er is nog geen planning actief. Automatisch concepten maken wordt beschikbaar zodra de AI-koppeling en een planning zijn ingesteld.</B></p></div></div></>}
 {view==='teacher-students'&&role==='teacher_admin'&&<><div className="page-heading"><div><div className="season-label"><Users size={15}/> VOOR DOCENTEN</div><h1><B>Studenten in beeld.</B></h1><p><B>Beheer je klassen, studenten en deelname in één overzicht.</B></p></div></div><TeacherDashboard/></>}
